1	export type Item = {
2	  type: string;
3	  material?: string;
4	  enchantment?: number;
5	  cursed?: boolean;
6	};
7	
8	export type Damage = {
9	  itemType: string;
10	  amount: number;
11	};
12	
13	export type Incident = {
14	  cause: string;
15	  damages: Damage[];
16	};
17	
18	export type Step = {
19	  op: string;
20	  items?: Item[];
21	  policy?: number;
22	  incident?: Incident;
23	};
24	
25	export type Customer = {
26	  yearsWithMHPCO: number;
27	};
28	
29	export type Scenario = {
30	  customer: Customer;
31	  steps: Step[];
32	};
33	
34	export type QuoteResult = {
35	  premium: number;
36	};
37	
38	export type ClaimResult = {
39	  payout: number;
40	  remainingCap: number;
41	};
42	
43	// A scenario's results are heterogeneous: a quote step yields a premium, a
44	// claim step a payout and the cap left on its policy.
45	export type StepResult = QuoteResult | ClaimResult;
46	
47	export type ScenarioResults = {
48	  results: StepResult[];
49	};
50	
51	// --- Quotes ------------------------------------------------------------------
52	
53	const PROCESSING_FEE = 5;
54	
55	const BASE_PREMIUM_BY_TYPE: Record<string, number> = {
56	  sword: 100,
57	  amulet: 60,
58	  staff: 80,
59	  potion: 40,
60	  rune: 25,
61	  moonstone: 25,
62	};
63	
64	// Charged on every quote, unconditionally — it is the cost of assessing the
65	// items, not a penalty for being a new customer. Named "first insurance" in
66	// some of the domain material, which misleads: it does not depend on customer
67	// history or on the quote's position in the scenario.
68	const INITIAL_ASSESSMENT_SURCHARGE_PERCENT = 10;
69	
70	const percentOf = (amount: number, percent: number): number =>
71	  (amount * percent) / 100;
72	
73	const itemBasePremium = (item: Item): number =>
74	  BASE_PREMIUM_BY_TYPE[item.type];
75	
76	const BLOCK_SIZE = 3;
77	
78	const BLOCK_PREMIUM = 60;
79	
80	const sumOf = (amounts: number[]): number =>
81	  amounts.reduce((sum, amount) => sum + amount, 0);
82	
83	const formsABlock = (items: Item[]): boolean => items.length === BLOCK_SIZE;
84	
85	const sumOfItemBasePremiums = (items: Item[]): number =>
86	  sumOf(items.map(itemBasePremium));
87	
88	// Items of the same type are "alike" and are priced together, so the policy
89	// base premium is computed group by group rather than item by item.
90	const alikeGroups = (items: Item[]): Item[][] => {
91	  const groupsByType = new Map<string, Item[]>();
92	
93	  for (const item of items) {
94	    groupsByType.set(item.type, [...(groupsByType.get(item.type) ?? []), item]);
95	  }
96	
97	  return [...groupsByType.values()];
98	};
99	
100	const alikeGroupBasePremium = (alikeItems: Item[]): number =>
101	  formsABlock(alikeItems)
102	    ? BLOCK_PREMIUM
103	    : sumOfItemBasePremiums(alikeItems);
104	
105	const policyBasePremium = (items: Item[]): number =>
106	  sumOf(alikeGroups(items).map(alikeGroupBasePremium));
107	
108	const roundPremiumInMHPCOsFavor = (amount: number): number =>
109	  Math.ceil(amount);
110	
111	// The inputs a single quote is computed from: `items` drives the base premium
112	// and item-scoped surcharges, `customer` and `precedingQuoteCount` drive the
113	// policy-wide modifiers. The count is of preceding QUOTE steps, not of steps in
114	// general — a claim step is not a contract and must not trigger the follow-up
115	// discount.
116	type QuoteRequest = {
117	  customer: Customer;
118	  items: Item[];
119	  precedingQuoteCount: number;
120	};
121	
122	const LOYALTY_YEARS = 2;
123	
124	const LOYALTY_DISCOUNT_PERCENT = 20;
125	
126	// Modifier percents are signed so surcharges and discounts can be summed
127	// uniformly; a discount enters the sum as its negation.
128	const asDiscount = (percent: number): number => -percent;
129	
130	const isLoyal = (customer: Customer): boolean =>
131	  customer.yearsWithMHPCO >= LOYALTY_YEARS;
132	
133	const FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT = 15;
134	
135	const isFollowUpContract = (request: QuoteRequest): boolean =>
136	  request.precedingQuoteCount > 0;
137	
138	const policyModifierPercents = (request: QuoteRequest): number[] => [
139	  INITIAL_ASSESSMENT_SURCHARGE_PERCENT,
140	  ...(isLoyal(request.customer) ? [asDiscount(LOYALTY_DISCOUNT_PERCENT)] : []),
141	  ...(isFollowUpContract(request)
142	    ? [asDiscount(FOLLOW_UP_CONTRACT_DISCOUNT_PERCENT)]
143	    : []),
144	];
145	
146	// Policy-wide modifiers do NOT compound: each is an independent percentage of
147	// the policy base premium, and they are summed. Chaining them (base * 1.1 * 0.8)
148	// would give a different, wrong answer.
149	const applyPolicyModifiers = (
150	  basePremium: number,
151	  request: QuoteRequest,
152	): number =>
153	  basePremium +
154	  sumOf(
155	    policyModifierPercents(request).map((percent) =>
156	      percentOf(basePremium, percent),
157	    ),
158	  );
159	
160	const CURSE_SURCHARGE_PERCENT = 50;
161	
162	const HIGH_ENCHANTMENT_LEVEL = 5;
163	
164	const HIGH_ENCHANTMENT_SURCHARGE_PERCENT = 30;
165	
166	const isHighlyEnchanted = (item: Item): boolean =>
167	  (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
168	
169	const isCursed = (item: Item): boolean => item.cursed === true;
170	
171	type ItemSurchargeRule = {
172	  applies: (item: Item) => boolean;
173	  percent: number;
174	};
175	
176	const ITEM_SURCHARGE_RULES: ItemSurchargeRule[] = [
177	  { applies: isCursed, percent: CURSE_SURCHARGE_PERCENT },
178	  { applies: isHighlyEnchanted, percent: HIGH_ENCHANTMENT_SURCHARGE_PERCENT },
179	];
180	
181	// Item-scoped surcharges are charged on the item's own base premium, so they
182	// must NOT go through applyPolicyModifiers.
183	const itemSurcharges = (item: Item): number =>
184	  sumOf(
185	    ITEM_SURCHARGE_RULES.filter((rule) => rule.applies(item)).map((rule) =>
186	      percentOf(itemBasePremium(item), rule.percent),
187	    ),
188	  );
189	
190	const policyItemSurcharges = (items: Item[]): number =>
191	  sumOf(items.map(itemSurcharges));
192	
193	const quotePremium = (request: QuoteRequest): number =>
194	  roundPremiumInMHPCOsFavor(
195	    applyPolicyModifiers(policyBasePremium(request.items), request) +
196	      policyItemSurcharges(request.items) +
197	      PROCESSING_FEE,
198	  );
199	
200	// --- Claims -----------------------------------------------------------------
201	// An item's insurance value is what it is worth if destroyed, and is unrelated
202	// to its premium: the premium is what the customer pays to be covered. The two
203	// tables below happen to agree on a 10x ratio today, but that is a property of
204	// the current price list and not a rule of the domain — repricing premiums must
205	// not silently revalue payouts, so they stay separate.
206	const INSURANCE_VALUE_BY_TYPE: Record<string, number> = {
207	  sword: 1000,
208	  amulet: 600,
209	  staff: 800,
210	  potion: 400,
211	  rune: 250,
212	  moonstone: 250,
213	};
214	
215	const insuranceSum = (items: Item[]): number =>
216	  sumOf(items.map((item) => INSURANCE_VALUE_BY_TYPE[item.type]));
217	
218	// A policy pays out at most twice what it insures.
219	const CAP_MULTIPLIER = 2;
220	
221	const policyCap = (items: Item[]): number =>
222	  CAP_MULTIPLIER * insuranceSum(items);
223	
224	const DEDUCTIBLE = 100;
225	
226	const HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL = 8;
227	
228	const HALF_REIMBURSEMENT_PERCENT = 50;
229	
230	const isHalfReimbursed = (item: Item): boolean =>
231	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_ENCHANTMENT_LEVEL;
232	
233	const damagedItem = (insuredItems: Item[], damage: Damage): Item | undefined =>
234	  insuredItems.find((item) => item.type === damage.itemType);
235	
236	// A reimbursement clause pays a percentage of the damage other than the default
237	// 100 %. Clauses are listed in precedence order and the first applicable one
238	// wins — the dragon-material clause will slot in below the enchantment one.
239	type ReimbursementClause = {
240	  applies: (item: Item) => boolean;
241	  percent: number;
242	};
243	
244	const REIMBURSEMENT_CLAUSES: ReimbursementClause[] = [
245	  { applies: isHalfReimbursed, percent: HALF_REIMBURSEMENT_PERCENT },
246	];
247	
248	const FULL_REIMBURSEMENT_PERCENT = 100;
249	
250	// No insured item means no clause applies. That an unmatched damage reimburses
251	// in full is not a rule of the domain, only the current default: the pending
252	// "item not part of the policy" test will reject such a claim outright.
253	const reimbursementPercent = (item: Item | undefined): number =>
254	  (item === undefined
255	    ? undefined
256	    : REIMBURSEMENT_CLAUSES.find((clause) => clause.applies(item))?.percent) ??
257	  FULL_REIMBURSEMENT_PERCENT;
258	
259	// What a damage entry reimburses before the deductible: a percentage of the
260	// damage amount, decided by the clauses covering the damaged item.
261	const reimbursableAmount = (insuredItems: Item[], damage: Damage): number =>
262	  percentOf(
263	    damage.amount,
264	    reimbursementPercent(damagedItem(insuredItems, damage)),
265	  );
266	
267	// The deductible applies once per damage event, i.e. per entry in `damages`,
268	// and always last — after the clause has decided the reimbursable amount.
269	const damagePayout = (insuredItems: Item[], damage: Damage): number =>
270	  reimbursableAmount(insuredItems, damage) - DEDUCTIBLE;
271	
272	// --- Running a scenario ------------------------------------------------------
273	
274	const isQuote = (step: Step): boolean => step.op === "quote";
275	
276	// What the scenario has accumulated so far. Steps are folded rather than mapped
277	// because a step's result depends on the steps before it: `precedingQuoteCount`
278	// drives the follow-up discount today, and claim steps will thread a remaining
279	// cap through the same carry.
280	type ScenarioState = {
281	  results: StepResult[];
282	  precedingQuoteCount: number;
283	  // Policies created by earlier quote steps, keyed by that step's index — a
284	  // claim names its policy that way (`step.policy`).
285	  policiesByStep: Map<number, Item[]>;
286	};
287	
288	const INITIAL_STATE: ScenarioState = {
289	  results: [],
290	  precedingQuoteCount: 0,
291	  policiesByStep: new Map(),
292	};
293	
294	// Running a step is a state transition: it reads the carry accumulated by the
295	// preceding steps and returns the next carry. Every step kind gets its own
296	// runner, so `runStep` below is pure dispatch on `op` — the place a claim runner
297	// will be added without touching the quote path.
298	type StepRunner = (
299	  customer: Customer,
300	  state: ScenarioState,
301	  step: Step,
302	  stepIndex: number,
303	) => ScenarioState;
304	
305	const appendResult = (
306	  state: ScenarioState,
307	  result: StepResult,
308	): ScenarioState => ({ ...state, results: [...state.results, result] });
309	
310	const runQuoteStep: StepRunner = (customer, state, step, stepIndex) => {
311	  const items = step.items ?? [];
312	
313	  const premium = quotePremium({
314	    customer,
315	    items,
316	    precedingQuoteCount: state.precedingQuoteCount,
317	  });
318	
319	  return {
320	    ...appendResult(state, { premium }),
321	    precedingQuoteCount: state.precedingQuoteCount + 1,
322	    policiesByStep: new Map(state.policiesByStep).set(stepIndex, items),
323	  };
324	};
325	
326	// A claim names its policy by the index of the quote step that created it. An
327	// unnamed or unknown policy currently yields no insured items, and so a cap of
328	// 0 — the pending error-handling tests will replace this with a rejection.
329	const insuredItemsFor = (state: ScenarioState, step: Step): Item[] =>
330	  step.policy === undefined ? [] : (state.policiesByStep.get(step.policy) ?? []);
331	
332	const runClaimStep: StepRunner = (_customer, state, step) => {
333	  const damages = step.incident?.damages ?? [];
334	  const insuredItems = insuredItemsFor(state, step);
335	
336	  const payout = sumOf(
337	    damages.map((damage) => damagePayout(insuredItems, damage)),
338	  );
339	  const cap = policyCap(insuredItems);
340	
341	  return appendResult(state, { payout, remainingCap: cap - payout });
342	};
343	
344	const runStep: StepRunner = (customer, state, step, stepIndex) =>
345	  isQuote(step)
346	    ? runQuoteStep(customer, state, step, stepIndex)
347	    : runClaimStep(customer, state, step, stepIndex);
348	
349	// The customer is scenario-wide, so it is closed over rather than threaded
350	// through the fold alongside the per-step state.
351	const stepRunnerFor =
352	  (customer: Customer) =>
353	  (state: ScenarioState, step: Step, stepIndex: number) =>
354	    runStep(customer, state, step, stepIndex);
355	
356	export const runScenario = (scenario: Scenario): ScenarioResults => ({
357	  results: scenario.steps.reduce(stepRunnerFor(scenario.customer), INITIAL_STATE)
358	    .results,
359	});
